&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience selling, buying, or integrating Esri products like ArcGIS.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience working in the Electric Utility Industry or Power Engineering Industry.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience working as a field technician or field engineer in the utility industry, especially as a substation technician, utility inspector, or lineman.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;

startx-valtech:greenhouse:4751796101.descriptionHtml:
&lt;p&gt;&lt;span class=&quot;TextRun SCXW246265904 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;Why Valtech? &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;We’re&lt;/span&gt; &lt;span class=&quot;NormalTextRun ContextualSpellingAndGrammarErrorV2Themed SCXW246265904 BCX0&quot;&gt;the&lt;/span&gt; &lt;span class=&quot;NormalTextRun ContextualSpellingAndGrammarErrorV2Themed SCXW246265904 BCX0&quot;&gt;experience&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt; innovation company &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;- &lt;/span&gt;&lt;span class=&quot;NormalTextRun CommentStart SCXW246265904 BCX0&quot;&gt;a&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt; trusted partner&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt; to the world’s most recognized brands. To our people we offer &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;growth opportunities, &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;a &lt;/span&gt;&lt;span class=&quot;NormalTextRun ContextualSpellingAndGrammarErrorV2Themed SCXW246265904 BCX0&quot;&gt;values&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;-driven culture, &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;international &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;careers&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt; and the chance to shape the future of experience.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP CommentStart SCXW246265904 BCX0&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;The role &lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We are seeking a&lt;strong&gt; Senior Google Cloud Data Engineer&lt;/strong&gt; with a strong background in data engineering and a hands-on approach to driving projects independently from start to finish. This role requires someone who thrives in a proactive environment and can deliver impactful solutions in cybersecurity analytics and anomaly detection.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;The ideal candidate will have experience in developing dashboards and insights to detect and visualize security threats, including executive-level dashboards. Comfort with Looker Core,&amp;nbsp;BigQuery,&amp;nbsp;SQL, and Python&amp;nbsp;is&amp;nbsp;essential, along with familiarity in&amp;nbsp;Machine&amp;nbsp;Learning for anomaly detection, alerting mechanisms, and data manipulation.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;This position is onsite in Greater New York City area 3 days per week, and remote 2 days per week.&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Role responsibilities&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Drive projects independently, ensuring timely delivery and high-quality outcomes.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Lead and execute projects related to cybersecurity, including anomaly detection in data to identify potential security threats.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Develop dashboards and visuals for operational and executive use, leveraging Looker Core and BigQuery.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Implement alerting systems to proactively detect anomalies and security issues.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Design and implement data ingestion and transformation pipelines leveraging Google Cloud Dataflow / Apache Beam and BigQuery for analytics and large-scale querying.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Implement Machine Learning models (specifically leveraging BigQuery ML or Vertex AI) to identify statistical outliers, potential intrusions, and fraudulent patterns in network traffic.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Build fault-tolerant, self-healing, adaptive, and highly accurate streaming and batch data pipelines on GCP.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Perform data manipulation and analysis to support threat detection and reporting.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Collaborate closely with cross-functional teams to ensure data quality, availability, and reliability across cloud environments.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Develop and maintain technical documentation for all assigned systems and projects.&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Must have qualifications&lt;/span&gt;&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;To be considered for this role, you must meet the following essential qualifications:&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Candidates must be legally authorized to work in the United States and must hold either U.S. citizenship or lawful permanent resident (Green Card) status.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Strong expertise in:&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;
&lt;ul&gt;
&lt;li&gt;Python - for building data pipelines, processing tasks, and automation&amp;nbsp;&lt;/li&gt;
&lt;li&gt;SQL - Advanced SQL capabilities (nested fields, analytic functions).&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;Hands-on experience with Core GCP Data Stack:&amp;nbsp;
&lt;ul&gt;
&lt;li&gt;BigQuery: Expert-level SQL, performance tuning, and specifically BigQuery ML (BQML) for implementing logistic regression or k-means clustering on data in-place.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Dataflow (Apache Beam): Strong proficiency in writing data pipelines (Python or Java) handling windowing, watermarks, and triggers for streaming data.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Pub/Sub: Experience with event-driven architecture and message queuing.&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;Hands-on experience with Visualization &amp;amp; BI: &amp;nbsp; &amp;nbsp; &amp;nbsp;
&lt;ul&gt;
&lt;li&gt;Looker Core – Advanced proficiency in LookML (not just drag-and-drop), including derived tables, explores, and Liquid syntax.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Semantic Modeling: Develop robust LookML models to create a trusted layer of data governance, ensuring metrics are consistent across the organization.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Dashboard Creation: Design intuitive, high-impact dashboards in Looker for two distinct audiences: Operational teams (real-time threat monitoring) and Executives (risk posture and compliance reporting&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;Familiarity with Alerting Frameworks&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Ability to work independently and drive projects solo with minimal supervision&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Outstanding soft and communication skills&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Nice to have qualifications &lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li style=&quot;font-weight: bold;&quot;&gt;&lt;strong&gt;Google Cloud Professional Data Engineer certification&amp;nbsp;&lt;/strong&gt;&lt;/li&gt;
&lt;li style=&quot;font-weight: bold;&quot;&gt;&lt;strong&gt;Google Professional Machine Learning Engineer certification&amp;nbsp;&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;Google Cloud Professional Cloud Architect certification &amp;nbsp;&lt;/li&gt;
&lt;li&gt;Bachelor’s or Master’s degree in a quantitative or technical field (e.g., Computer Science, Engineering, Statistics) &amp;nbsp; &amp;nbsp;&lt;/li&gt;
&lt;li&gt;Working knowledge of cloud architecture components in GCP &amp;nbsp;&lt;/li&gt;
&lt;li&gt;Proficiency in Big Data environments and tools such as Spark, Hive, Impala, Pig, etc. &amp;nbsp;&lt;/li&gt;
&lt;li&gt;Proficiency in Terraform&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Familiarity with front and back-end web application stacks and frameworks, and API design and usage (REST/GraphQL) &amp;nbsp; &amp;nbsp;&lt;/li&gt;
&lt;li&gt;Experience leading and managing technical data/analytics/machine learning projects &amp;nbsp;&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span class=&quot;TextRun MacChromeBold SCXW105898609 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW105898609 BCX0&quot;&gt;If you do not meet all the listed qualifications or have gaps in your experience, we still encourage you to apply. At Valtech, we recognize that talent comes in many forms, and we value diverse perspectives and a willingness to learn.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP SCXW105898609 BCX0&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;br&gt;&lt;br&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;The benefits &lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;This is a &lt;strong&gt;full-time&lt;/strong&gt; position based in New York, United States. The offered salary range is&lt;strong&gt; &lt;/strong&gt;$170,000-240,000&lt;strong&gt; &lt;/strong&gt;annually, depending on experience and location.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Beyond a competitive compensation package, we offer:&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Flexibility, with remote and hybrid work options (country-dependent)&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Career advancement, with international mobility and professional development programs&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Learning and development, with access to cutting-edge tools, training and industry experts&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&lt;span data-olk-copy-source=&quot;MessageBody&quot;&gt;Medical, dental, and vision insurance for you and your family, plus employer contributions to Health Savings Accounts&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Our benefits are tailored to each location. Your Talent Partner will provide full details during the hiring process.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Your application process&lt;/span&gt;&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Once you apply, our Talent Acquisition team will review your application. If your skills and experience align with the role, we’ll reach out for next steps.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt; &lt;span data-teams=&quot;true&quot;&gt;Your CV should cover key information on relevant experiences and expertise. We do not require information such as age, gender, marital status, or a headshot in your application. We review all candidates based on skills, experience, and potential.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;⚠️ Beware of recruitment fraud: Only engage with official Valtech email addresses.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We are committed to inclusion and accessibility. If you need reasonable accommodations during the interview process, please either indicate it in your application or let your Talent Partner know.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;About Valtech&lt;/span&gt;&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Valtech is the experience innovation company that exists to unlock a better way to experience the world. By blending crafts, categories, and cultures, we help brands unlock new value in an increasingly digital world.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;At the intersection of data, AI, creativity, and technology, we drive transformation for leading organizations, including L’Oréal, Mars, Audi, P&amp;amp;G, Volkswagen Dolby, and more.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;At Valtech, we don’t just talk about transformation. We make it happen. Our people are the heart of our success, and we foster a workplace where everyone has the support to thrive, grow and innovate.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Are you ready to create what’s next? Join us.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;For applicants in California, please see Valtech&#39;s CPRA Privacy Notice &lt;a href=&quot;https://www.valtech.com/california-privacy-notice-for-job-applicants/&quot; target=&quot;_blank&quot;&gt;here&lt;/a&gt;.&lt;/span&gt;&lt;/p&gt;

